import { eventFacts, settlementFacts, activityRange } from './facts.js';
import { fields, uint, playerAddress, bigintJSON } from './state.js';
import { registrationStart } from './positions.js';
import { AbiCoder, id, keccak256 } from '../vendor/ethers-app.mjs';

export async function coinflipDay(s, day, player, signal) {
  const rows = await settlementFacts(s, 'COINFLIP', ['CoinflipDayResolved'], day, { signal });
  const previous = day > 1 ? await settlementFacts(s, 'COINFLIP', ['CoinflipDayResolved'], day - 1, { signal }) : [];
  const stakeRange = player ? await activityRange(s, Math.max(1, day - 1), signal) : null;
  const stakes = player ? await eventFacts(s, ['CoinflipStakeUpdated'], { contract: 'COINFLIP', day, player, fromBlock: stakeRange.fromBlock, signal }) : [];
  const row = rows.at(-1); const stake = stakes.at(-1);
  return { day, win: row?.args.win ?? null, rewardPercent: row ? Number(row.args.rewardPercent) : null,
    bountyAfter: row?.args.recordPoolAfter ?? null, bountyPaid: null, bountyRecipient: null,
    blockNumber: row?.blockNumber ?? null, previousResolvedBlock: previous.at(-1)?.blockNumber ?? null,
    playerStake: stake?.args.newTotal ?? null, playerStakeBlock: stake?.blockNumber ?? null };
}

// Audit 92a1358d0: the Decimator is a shared-dice craps battle (DegenerusGameDecimatorModule.sol).
// A wallet holds ONE entry per event and every burn adds to the stack and re-sets the board. Since
// audit 32c604531 decBattlePlayers[player] = lvl << 64 | id names the wallet's latest entry and
// decBattleEntries[lvl << 64 | id] = owner | chips << 160 | stack << 190, the stack in whole FLIP;
// a heap node is score << 64 | id. Sealing stores the round's word
// (DecimatorResolved); each entry's final coin drops tails, heads play the event's dice
// (DecimatorRun), the best min(100, ceil(N/10)) stack x peak are ranked (DecimatorRanked) and
// paid in heap order as claimable ETH or half whale passes (DecimatorClaimed). There is no
// claim. Round phase: 0 entry, 1 runs, 2 payouts, 3 done.
export const DECIMATOR_ENTRY_EVENTS = ['DecBurnRecorded'];
const COIN_TAG = id('decimator.battle.final-coin.v1');
const HALF_WHALE_PASS_WEI = 2_250_000_000_000_000_000n;
const MASK_64 = (1n << 64n) - 1n;
const coder = AbiCoder.defaultAbiCoder();
const ROUND_STATUS = ['open', 'settling', 'closed', 'closed'];

export function decimatorEntryWord(word) {
  const value = BigInt(word ?? 0);
  return { chips: Number((value >> 160n) & 0x3FFFFFFFn), stack: (value >> 190n) * 10n ** 18n };
}

/** The wallet's entry id for `level`, or 0n when its latest entry is another event's. */
async function decimatorEntryId(s, level, player) {
  const latest = BigInt(await s.field('GAME', 'decBattlePlayers', player));
  return Number((latest >> 64n) & 0xFFFFFFn) === level ? latest & MASK_64 : 0n;
}

/** DecimatorModule._run's final coin: heads plays the dice, tails is out before the engine runs. */
export function decimatorCoinHeads(rngWord, level, entryId) {
  const hash = keccak256(coder.encode(['bytes32', 'uint256', 'uint24', 'uint64'], [COIN_TAG, BigInt(rngWord), level, BigInt(entryId)]));
  return (BigInt(hash) & 1n) === 1n;
}

/** DecimatorModule._payTerms: what place `position` of the heap is paid (0 is the champion). */
export function decimatorPayout(poolWei, winners, position) {
  const pool = BigInt(poolWei); const n = BigInt(winners); const at = Number(position);
  if (n === 0n) return { ethWei: 0n, halfPasses: 0n };
  const base = (pool - pool / 20n) / n;
  const champ = pool - base * (n - 1n);
  const champPasses = champ / 2n / HALF_WHALE_PASS_WEI;
  if (at === 0) return { ethWei: champ - champPasses * HALF_WHALE_PASS_WEI, halfPasses: champPasses };
  const passMode = n > 1n && base >= HALF_WHALE_PASS_WEI;
  if (!passMode) return { ethWei: base, halfPasses: 0n };
  if ((at & 1) === 0) return { ethWei: 0n, halfPasses: base / HALF_WHALE_PASS_WEI };
  const passWinners = (n - 1n) / 2n;
  const ethWinners = n - 1n - passWinners;
  const perEth = (passWinners * (base % HALF_WHALE_PASS_WEI)) / ethWinners;
  return { ethWei: base + perEth, halfPasses: 0n };
}

export async function decimatorPlayer(s, level, player) {
  const [entryId, round] = await Promise.all([decimatorEntryId(s, level, player), s.field('GAME', 'decBattleRounds', level)]);
  const entry = { entryId, ...decimatorEntryWord(entryId ? await s.field('GAME', 'decBattleEntries', (BigInt(level) << 64n) | entryId) : 0n) };
  const phase = Number(round.phase);
  const row = { player, level, entryId: entry.entryId ? String(entry.entryId) : null, stack: String(entry.stack),
    chips: entry.entryId ? entry.chips : null, phase, entrants: Number(round.count), winners: Number(round.winners),
    poolWei: String(round.poolWei), roundStatus: ROUND_STATUS[phase] ?? 'closed', coin: null, peak: null,
    winner: false, champion: false, claimed: false, payoutAmount: '0', ethAmount: '0', lootboxAmount: '0',
    halfPasses: '0', cashOnly: false, effectiveAmount: String(entry.stack), weightedAmount: String(entry.stack) };
  if (!entry.entryId || phase === 0) return row;
  if (!decimatorCoinHeads(round.rngWord, level, entry.entryId)) return { ...row, coin: 'tails' };
  row.coin = 'heads';
  const [runs, claims] = await Promise.all([
    eventFacts(s, ['DecimatorRun'], { contract: 'GAME', filters: { lvl: level, entryId: entry.entryId } }),
    phase >= 2 ? eventFacts(s, ['DecimatorClaimed'], { contract: 'GAME', player, filters: { lvl: level } }) : [],
  ]);
  row.peak = runs.at(-1) ? String(runs.at(-1).args.normalizedPeak) : null;
  if (phase < 2) return row;
  row.champion = BigInt(round.champion) === entry.entryId;
  const claim = claims.at(-1);
  let pay = null;
  if (claim) {
    row.claimed = true;
    pay = { ethWei: BigInt(claim.args.amountWei), halfPasses: BigInt(claim.args.halfPasses) };
  } else if (phase === 2) {
    // Unpaid winners are still in the heap at positions paid..winners-1, in payout order.
    const paid = Number(round.paid); const winners = Number(round.winners);
    const nodes = await Promise.all(Array.from({ length: Math.max(0, winners - paid) }, (_, i) => s.field('GAME', 'decBattleHeap', paid + i)));
    const at = nodes.findIndex(node => (BigInt(node) & MASK_64) === entry.entryId);
    if (at >= 0) pay = decimatorPayout(round.poolWei, winners, paid + at);
  }
  if (!pay) return row;
  row.winner = true;
  row.ethAmount = String(pay.ethWei); row.payoutAmount = String(pay.ethWei); row.halfPasses = String(pay.halfPasses);
  row.cashOnly = pay.halfPasses === 0n;
  return row;
}

export async function readGameRoute(s, url, { signal } = {}) {
  const p = url.pathname.split('/').filter(Boolean); const q = url.searchParams;
  if (p[0] === 'game' && p[1] === 'coinflip' && p[2] === 'day') return coinflipDay(s, uint(p[3]), q.has('player') ? playerAddress(q.get('player')) : null, signal);
  if (p[0] === 'game' && p[1] === 'quests' && p[2] === 'day') {
    const day = uint(p[3]);
    const active = await s.call('QUESTS', 'getActiveQuests');
    if (active.every(quest => Number(quest.day) === day)) return { day, quests: active.map((quest, slot) => ({ slot, questType: Number(quest.questType), flags: quest.highDifficulty ? 1 : 0,
      target: String(quest.requirements.mints || quest.requirements.tokenAmount) })) };
    const rows = await settlementFacts(s, 'QUESTS', ['QuestSlotRolled'], day, { signal });
    return { day, quests: rows.map(row => ({ slot: Number(row.args.slot), questType: Number(row.args.questType), flags: Number(row.args.flags), target: null })) };
  }
  if (p[0] === 'player' && p[2] === 'decimator') return decimatorPlayer(s, uint(q.get('level')), playerAddress(p[1]));
  if (p[0] === 'game' && p[1] === 'decimator' && /^\d+$/.test(p[2])) {
    // Each entry's last DecBurnRecorded carries its running stack.
    const level = uint(p[2]); const stacks = new Map();
    for (const row of await eventFacts(s, ['DecBurnRecorded'], { contract: 'GAME', filters: { lvl: level } })) stacks.set(String(row.args.player).toLowerCase(), BigInt(row.args.stack));
    const round = await s.field('GAME', 'decBattleRounds', level);
    return { level, totalStack: String([...stacks.values()].reduce((a, b) => a + b, 0n)), entrants: Number(round.count) };
  }
  if (p[0] === 'player' && p[2] === 'baf') {
    const level = uint(q.get('level')); const player = playerAddress(p[1]);
    const [entry, header, top] = await Promise.all([
      s.field('JACKPOTS', 'bafPlayer', level, player), s.field('JACKPOTS', 'bafLevel', level),
      Promise.all([0, 1, 2, 3].map(i => s.field('JACKPOTS', 'bafTop', level, i))),
    ]);
    const closed = header.skipped || header.epoch > 0n;
    const board = closed ? (await (await import('./boards.js')).bafBoard(s,level,signal)).entries : top;
    const rank = board.findIndex(row => row.player === player);
    return { player, level, score: String(entry.total), rank: rank < 0 ? null : rank + 1,
      totalParticipants: null, roundStatus: header.skipped ? 'skipped' : header.epoch > 0n ? 'closed' : 'open', rankScope: 'top-four' };
  }
  if (url.pathname === '/degenerette/hero') {
    const day = uint(q.get('day') ?? s.client.dayAt(s.block.timestamp));
    const words = await Promise.all([0, 1, 2, 3].map(i => s.field('GAME', 'dailyHeroWagers', day, i)));
    const items = words.flatMap((word, quadrant) => Array.from({ length: 8 }, (_, symbol) => ({ quadrant, symbol, wagerUnits: Number((word >> BigInt(symbol * 32)) & 0xffffffffn) })))
      .filter(row => row.wagerUnits).sort((a, b) => b.wagerUnits - a.wagerUnits);
    const totalWagerUnits = items.reduce((sum, row) => sum + row.wagerUnits, 0);
    return { day, totalWagerUnits, count: items.length, leader: items[0] ?? null,
      items: items.slice(0, uint(q.get('limit') ?? 5, 32)).map((row, i) => ({ ...row, rank: i + 1, sharePct: row.wagerUnits * 100 / totalWagerUnits, isLeader: i === 0 })) };
  }
  if (url.pathname === '/game/protocol-boon-draws') {
    const player = q.has('player') ? playerAddress(q.get('player')) : undefined;
    const currentDay = s.client.dayAt(s.block.timestamp); const { fromBlock } = await activityRange(s, Math.max(1, currentDay - 2), signal);
    const logs = await eventFacts(s, ['ProtocolBoonDrawEntered', 'ProtocolBoonDrawAwarded'], { contract: 'GAME', player, fromBlock, signal });
    const limit = uint(q.get('limit') ?? 50, 200);
    // Entries are ETH Degenerette hero bets (symbol 0 → Vault, 6 → sDGNRS); `amount` is the
    // wagered wei and `weight` the bet's wager units × activity multiplier.
    const map = row => ({ ...row.args, player: row.args.player ?? row.args.winner, day: Number(row.args.day),
      entryIndex: Number(row.args.entryIndex), slot: row.args.slot == null ? undefined : Number(row.args.slot), boonType: row.args.boonType == null ? undefined : Number(row.args.boonType),
      blockNumber: String(row.blockNumber), transactionHash: row.transactionHash, logIndex: row.logIndex });
    return { entries: logs.filter(row => row.name === 'ProtocolBoonDrawEntered').reverse().slice(0, limit).map(map),
      awards: logs.filter(row => row.name === 'ProtocolBoonDrawAwarded').reverse().slice(0, limit).map(map) };
  }
  return undefined;
}
